import glob, re, collections, datetime
sev_re = re.compile(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[(ERROR|WARNING|INFO|DEBUG)\]')
per_day = collections.defaultdict(collections.Counter)
allc = collections.Counter()
for f in sorted(glob.glob('/app/logs/*.log')):
    for line in open(f):
        m = sev_re.match(line.strip())
        if not m: 
            print("NOMATCH:", repr(line)); continue
        per_day[m.group(1)][m.group(2)] += 1
        if m.group(2) in ('ERROR','WARNING','INFO'):
            allc[m.group(2)] += 1

def day(d):
    return per_day.get(d, collections.Counter())

for d in ['2025-08-06','2025-08-07','2025-08-08','2025-08-09','2025-08-10','2025-08-11','2025-08-12']:
    c = day(d)
    print(d, dict(c))
print("7d sum:", {k: sum(day(f'2025-08-{i:02d}')[k] for i in range(6,13)) for k in ('ERROR','WARNING','INFO')})
m = collections.Counter()
for i in range(1,13):
    m += day(f'2025-08-{i:02d}')
print("mtd sum:", dict(m))
EOF
